using ResolvedInstruction =
    std::variant<Add, Sub, Mul, Fma, Mad, Div, Rem, Min, Max, Abs, Neg, Popc,
                 Clz, Bfind, Bfe, Bfi, Brev, Set, Setp, Selp, Slct, Call, Bra,
                 Brx, Ret, Exit, Isspacep, Cvta, Cvt, Mov, Ld, Ldu, Shfl,
                 Prefetch, Prefetchu, Createpolicy, Applypriority, Discard, Cp,
                 St, Prmt, And, Or, Xor, Not, Lop3, Shf, Shl, Shr, Trap,
                 Setmaxnreg, Bar, Membar, Fence, Atom, Red, Activemask, Vote,
                 Mma, Ldmatrix>;

struct ResolvedFunction {
  binding::SymbolId symbol_id;
  std::string name;
  bool is_entry{};
  bool is_prototype{};
  std::vector<ResolvedInstruction> body;
  SourceRange range;
};

struct ResolvedModule {
  binding::SymbolTable symbols;
  std::vector<ResolvedFunction> functions;
  SourceRange range;
};

/** Check one resolved module against its source .version and .target profile.
 */
checker::CheckResult checkModuleAvailability(const syntax_ast::AstModule &ast,
                                             const ResolvedModule &module);

